insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('drawing-submissions','drawing-submissions',false,10485760,array['image/png','image/jpeg','image/webp']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
alter table dm_private.attempts add column upload_deadline timestamptz;
create table dm_private.drawing_uploads(id uuid primary key default gen_random_uuid(),attempt_id uuid not null references dm_private.attempts(id) on delete cascade,question_id uuid not null,student_id uuid not null references auth.users(id) on delete cascade,storage_path text unique not null,ordinal integer not null check(ordinal between 1 and 5),mime_type text not null check(mime_type in('image/png','image/jpeg','image/webp')),byte_size integer not null check(byte_size between 1 and 10485760),created_at timestamptz not null default now(),unique(attempt_id,question_id,ordinal));
create table dm_private.drawing_reviews(id uuid primary key default gen_random_uuid(),attempt_id uuid not null,question_id uuid not null,reviewer_id uuid references auth.users(id),status text not null default 'pending' check(status in('pending','assigned','reviewed','released')),criterion_marks jsonb,comments text,score numeric,override_reason text,reviewed_at timestamptz,released_at timestamptz,unique(attempt_id,question_id));
create table dm_private.drawing_review_audit(id bigint generated always as identity primary key,review_id uuid not null references dm_private.drawing_reviews(id) on delete cascade,actor_id uuid not null references auth.users(id),action text not null,payload jsonb not null default '{}',created_at timestamptz not null default now());
alter table dm_private.drawing_uploads enable row level security;alter table dm_private.drawing_reviews enable row level security;alter table dm_private.drawing_review_audit enable row level security;revoke all on dm_private.drawing_uploads,dm_private.drawing_reviews,dm_private.drawing_review_audit from anon,authenticated;
create or replace function public.register_drawing_upload(p_attempt_id uuid,p_question_id uuid,p_storage_path text,p_ordinal integer,p_mime_type text,p_byte_size integer) returns uuid language plpgsql security definer set search_path=pg_catalog,dm_private as $$ declare a dm_private.attempts;v uuid;begin if auth.role() is distinct from'service_role'then raise exception'Forbidden';end if;select*into a from dm_private.attempts where id=p_attempt_id for update;if a.id is null or coalesce(a.upload_deadline,a.deadline)<now()then raise exception'Upload window closed';end if;if not exists(select 1 from dm_private.attempt_items where attempt_id=a.id and question_id=p_question_id and kind='drawing')then raise exception'Drawing question not found';end if;insert into dm_private.drawing_uploads(attempt_id,question_id,student_id,storage_path,ordinal,mime_type,byte_size)values(a.id,p_question_id,a.user_id,p_storage_path,p_ordinal,p_mime_type,p_byte_size) returning id into v;return v;end$$;
create or replace function public.my_drawing_uploads(p_attempt_id uuid,p_question_id uuid) returns jsonb language sql stable security definer set search_path=pg_catalog,dm_private as $$select coalesce(jsonb_agg(jsonb_build_object('id',u.id,'ordinal',u.ordinal,'mimeType',u.mime_type,'byteSize',u.byte_size)order by u.ordinal),'[]')from dm_private.drawing_uploads u where u.attempt_id=p_attempt_id and u.question_id=p_question_id and u.student_id=auth.uid()$$;
create or replace function public.remove_drawing_upload(p_id uuid) returns text language plpgsql security definer set search_path=pg_catalog,dm_private as $$declare v text;begin delete from dm_private.drawing_uploads where id=p_id and student_id=auth.uid() and exists(select 1 from dm_private.attempts a where a.id=attempt_id and coalesce(a.upload_deadline,a.deadline)>now())returning storage_path into v;if v is null then raise exception'Upload unavailable';end if;return v;end$$;
create or replace function public.admin_drawing_queue()returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,dm_private as $$begin if not public.is_dmocks_admin()then raise exception'Admin access required';end if;return(select coalesce(jsonb_agg(jsonb_build_object('reviewId',r.id,'attemptId',r.attempt_id,'questionId',r.question_id,'status',r.status,'uploadCount',(select count(*)from dm_private.drawing_uploads u where u.attempt_id=r.attempt_id and u.question_id=r.question_id),'score',r.score)order by r.status,r.id),'[]')from dm_private.drawing_reviews r);end$$;
create or replace function public.admin_review_drawing(p_review_id uuid,p_criterion_marks jsonb,p_comments text,p_score numeric,p_override_reason text default null)returns void language plpgsql security definer set search_path=pg_catalog,public,dm_private as $$begin if not public.is_dmocks_admin()then raise exception'Admin access required';end if;if jsonb_typeof(p_criterion_marks)<>'object'or p_score<0 then raise exception'Invalid review';end if;update dm_private.drawing_reviews set reviewer_id=auth.uid(),status='reviewed',criterion_marks=p_criterion_marks,comments=nullif(trim(p_comments),''),score=p_score,override_reason=nullif(trim(p_override_reason),''),reviewed_at=now()where id=p_review_id;if not found then raise exception'Review not found';end if;insert into dm_private.drawing_review_audit(review_id,actor_id,action,payload)values(p_review_id,auth.uid(),'review',jsonb_build_object('criteria',p_criterion_marks,'score',p_score,'overrideReason',p_override_reason));end$$;
revoke all on function public.register_drawing_upload(uuid,uuid,text,integer,text,integer)from public,anon,authenticated;grant execute on function public.register_drawing_upload(uuid,uuid,text,integer,text,integer)to service_role;
revoke all on function public.my_drawing_uploads(uuid,uuid),public.remove_drawing_upload(uuid),public.admin_drawing_queue(),public.admin_review_drawing(uuid,jsonb,text,numeric,text)from public,anon;grant execute on function public.my_drawing_uploads(uuid,uuid),public.remove_drawing_upload(uuid),public.admin_drawing_queue(),public.admin_review_drawing(uuid,jsonb,text,numeric,text)to authenticated;
